using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace Stardust.EditorTools
{
    /// <summary>
    /// Imports the island generated by WorldGen (make_map.py + build_assets.py + export_unity.py):
    /// texture settings (texture arrays, masks), 36 terrain tiles, the Blender models (one submesh per
    /// material class), the materials and the data files read at runtime.
    /// Batch: Unity -batchmode -executeMethod Stardust.EditorTools.WorldImporter.ImportAll
    /// </summary>
    public static class WorldImporter
    {
        const string Src = "WorldGen/out";
        const string Tex = "Assets/World/Textures";
        const string Res = "Assets/World/Resources/World";
        public const float HMin = -80f, HRange = 440f;
        public const int Tiles = 6, TileRes = 513;
        public const float TileSize = 4096f;

        [MenuItem("Stardust/Import World (all)")]
        public static void ImportAll()
        {
            int code = 0;
            try
            {
                ImportTextures();
                ImportData();
                ImportMaterials();
                ImportModels();
                ImportTerrain();
                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();
                Debug.Log("[WorldImporter] done");
            }
            catch (Exception e)
            {
                Debug.LogError("[WorldImporter] " + e);
                code = 1;
            }
            if (Application.isBatchMode) EditorApplication.Exit(code);
        }

        static void Folder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            var parent = Path.GetDirectoryName(path).Replace('\\', '/');
            Folder(parent);
            AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
        }

        // ------------------------------------------------------------------ textures

        static void Platform(TextureImporter ti, string platform, int max, TextureImporterFormat fmt)
        {
            var ps = ti.GetPlatformTextureSettings(platform);
            ps.overridden = true;
            ps.maxTextureSize = max;
            ps.format = fmt;
            ps.compressionQuality = 80;
            ti.SetPlatformTextureSettings(ps);
        }

        static void ConfigArray(string file, int layers, bool srgb, bool normal)
        {
            var path = $"{Tex}/{file}";
            var ti = (TextureImporter)AssetImporter.GetAtPath(path);
            if (ti == null) throw new Exception("missing " + path);
            var s = new TextureImporterSettings();
            ti.ReadTextureSettings(s);
            s.textureType = TextureImporterType.Default;
            s.textureShape = TextureImporterShape.Texture2DArray;
            s.flipbookRows = layers;
            s.flipbookColumns = 1;
            s.sRGBTexture = srgb;
            s.mipmapEnabled = true;
            s.wrapMode = TextureWrapMode.Repeat;
            s.filterMode = FilterMode.Trilinear;
            s.aniso = 8;
            s.alphaSource = TextureImporterAlphaSource.FromInput;
            s.alphaIsTransparency = false;
            ti.SetTextureSettings(s);
            ti.maxTextureSize = 8192;
            Platform(ti, "Standalone", 8192, TextureImporterFormat.BC7);
            Platform(ti, "Android", 4096, normal ? TextureImporterFormat.ASTC_5x5 : TextureImporterFormat.ASTC_6x6);
            ti.SaveAndReimport();
        }

        static void Config2D(string file, bool srgb, bool mips, TextureWrapMode wrap, int pcMax, TextureImporterFormat pcFmt,
            int androidMax, TextureImporterFormat androidFmt, bool singleChannel = false, bool ui = false)
        {
            var path = $"{Tex}/{file}";
            var ti = (TextureImporter)AssetImporter.GetAtPath(path);
            if (ti == null) throw new Exception("missing " + path);
            ti.textureType = singleChannel ? TextureImporterType.SingleChannel : (ui ? TextureImporterType.Sprite : TextureImporterType.Default);
            if (ui) ti.spriteImportMode = SpriteImportMode.Single;
            ti.textureShape = TextureImporterShape.Texture2D;
            ti.sRGBTexture = srgb;
            ti.mipmapEnabled = mips;
            ti.wrapMode = wrap;
            ti.filterMode = mips ? FilterMode.Trilinear : FilterMode.Bilinear;
            ti.anisoLevel = mips ? 4 : 1;
            ti.alphaSource = TextureImporterAlphaSource.FromInput;
            ti.npotScale = TextureImporterNPOTScale.None;
            ti.maxTextureSize = 8192;
            if (singleChannel)
            {
                var s = new TextureImporterSettings();
                ti.ReadTextureSettings(s);
                s.singleChannelComponent = TextureImporterSingleChannelComponent.Red;
                ti.SetTextureSettings(s);
            }
            Platform(ti, "Standalone", pcMax, pcFmt);
            Platform(ti, "Android", androidMax, androidFmt);
            ti.SaveAndReimport();
        }

        [MenuItem("Stardust/Import World/1. Textures")]
        public static void ImportTextures()
        {
            ConfigArray("terrain_albedo.png", 8, true, false);
            ConfigArray("terrain_normal.png", 8, false, true);
            ConfigArray("model_albedo.png", 6, true, false);
            ConfigArray("model_normal.png", 6, false, true);
            Config2D("water_normal.png", false, true, TextureWrapMode.Repeat, 512, TextureImporterFormat.BC7, 512, TextureImporterFormat.ASTC_5x5);
            Config2D("biome.png", false, true, TextureWrapMode.Clamp, 2048, TextureImporterFormat.BC7, 1024, TextureImporterFormat.ASTC_6x6);
            Config2D("roads.png", false, true, TextureWrapMode.Clamp, 4096, TextureImporterFormat.BC4, 2048, TextureImporterFormat.ASTC_6x6, true);
            Config2D("ocean_mask.png", false, true, TextureWrapMode.Clamp, 2048, TextureImporterFormat.BC4, 1024, TextureImporterFormat.ASTC_6x6, true);
            Config2D("minimap.png", true, false, TextureWrapMode.Clamp, 2048, TextureImporterFormat.BC7, 2048, TextureImporterFormat.ASTC_6x6, false, true);
            // the HUD loads the map at runtime: keep a copy in Resources
            Folder(Res);
            File.Copy($"{Tex}/minimap.png", $"{Res}/minimap.png", true);
            AssetDatabase.ImportAsset($"{Res}/minimap.png");
            var mi = (TextureImporter)AssetImporter.GetAtPath($"{Res}/minimap.png");
            mi.textureType = TextureImporterType.Default;
            mi.sRGBTexture = true;
            mi.mipmapEnabled = true;
            mi.wrapMode = TextureWrapMode.Clamp;
            mi.filterMode = FilterMode.Trilinear;
            mi.npotScale = TextureImporterNPOTScale.None;
            Platform(mi, "Standalone", 2048, TextureImporterFormat.BC7);
            Platform(mi, "Android", 2048, TextureImporterFormat.ASTC_6x6);
            mi.SaveAndReimport();
            Debug.Log("[WorldImporter] textures configured");
        }

        /// <summary>Debug: mean colour of each slice of the texture arrays (checks the flipbook layer order).</summary>
        public static void DebugArrays()
        {
            var sb = new StringBuilder();
            foreach (var f in new[] { "terrain_albedo.png", "model_albedo.png" })
            {
                var path = $"{Tex}/{f}";
                var ti = (TextureImporter)AssetImporter.GetAtPath(path);
                ti.isReadable = true;
                ti.SaveAndReimport();
                var arr = AssetDatabase.LoadAssetAtPath<Texture2DArray>(path);
                sb.Append(f).Append(':');
                for (int s = 0; s < arr.depth; s++)
                {
                    var px = arr.GetPixels(s, 4);
                    Color m = Color.black;
                    foreach (var c in px) m += c;
                    m /= Mathf.Max(1, px.Length);
                    sb.Append($" [{s}] ({m.r * 255:0},{m.g * 255:0},{m.b * 255:0})");
                }
                sb.AppendLine();
                ti.isReadable = false;
                ti.SaveAndReimport();
            }
            Debug.Log("[WorldImporter] arrays " + sb);
            if (Application.isBatchMode) EditorApplication.Exit(0);
        }

        // ------------------------------------------------------------------ data files

        [MenuItem("Stardust/Import World/2. Data")]
        public static void ImportData()
        {
            Folder(Res);
            File.Copy($"{Src}/unity/world.json", $"{Res}/world.json", true);
            File.Copy($"{Src}/unity/veg.bin", $"{Res}/veg.bytes", true);
            AssetDatabase.ImportAsset($"{Res}/world.json");
            AssetDatabase.ImportAsset($"{Res}/veg.bytes");
            Debug.Log("[WorldImporter] data copied");
        }

        // ------------------------------------------------------------------ materials

        static Material Mat(string name, string shader, Action<Material> cfg)
        {
            Folder($"{Res}/Materials");
            var path = $"{Res}/Materials/{name}.mat";
            var sh = Shader.Find(shader);
            if (sh == null) throw new Exception("shader not found: " + shader);
            var m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null)
            {
                m = new Material(sh);
                AssetDatabase.CreateAsset(m, path);
            }
            m.shader = sh;
            m.enableInstancing = true;
            cfg(m);
            EditorUtility.SetDirty(m);
            return m;
        }

        static T Load<T>(string file) where T : UnityEngine.Object
        {
            var a = AssetDatabase.LoadAssetAtPath<T>($"{Tex}/{file}");
            if (a == null) throw new Exception($"missing {typeof(T).Name} {Tex}/{file}");
            return a;
        }

        /// <summary>Settings of each model material class (shared by world and vehicle variants).</summary>
        static void ClassSettings(Material m, MatClass c, bool ship)
        {
            var alb = Load<Texture2DArray>("model_albedo.png");
            var nrm = Load<Texture2DArray>("model_normal.png");
            m.SetTexture("_Albedo", alb);
            m.SetTexture("_Normal", nrm);
            m.SetFloat("_ObjectSpace", ship ? 1f : 0f);
            m.SetFloat("_Wind", 0f);
            m.SetFloat("_WindHeight", 8f);
            m.SetFloat("_Translucency", 0f);
            m.SetFloat("_GroundAO", ship ? 0f : 0.3f);
            m.SetFloat("_AOHeight", 4f);
            m.SetFloat("_Metallic", 0f);
            m.SetFloat("_Emission", 1f);
            m.SetFloat("_TexRough", 0.5f);
            m.SetFloat("_Cull", (float)CullMode.Back);
            m.SetColor("_Tint", Color.white);
            m.SetFloat("_Variation", ship ? 0f : c == MatClass.Foliage ? 0.2f : c == MatClass.Bark ? 0.12f : c == MatClass.Rock ? 0.1f : 0.05f);
            switch (c)
            {
                case MatClass.Rock:
                    m.SetFloat("_Layer", 0); m.SetFloat("_Tiling", ship ? 1.5f : 7f); m.SetFloat("_Detail", 0.75f); m.SetFloat("_NormalStrength", 1.25f);
                    break;
                case MatClass.Bark:
                    m.SetFloat("_Layer", 1); m.SetFloat("_Tiling", 2.5f); m.SetFloat("_Detail", 0.6f); m.SetFloat("_NormalStrength", 1.2f);
                    m.SetFloat("_Wind", 0.28f); m.SetFloat("_GroundAO", 0.45f); m.SetFloat("_AOHeight", 3f);
                    break;
                case MatClass.Concrete:
                    m.SetFloat("_Layer", 2); m.SetFloat("_Tiling", ship ? 1.2f : 4f); m.SetFloat("_Detail", 0.6f); m.SetFloat("_NormalStrength", 1f);
                    break;
                case MatClass.Metal:
                    m.SetFloat("_Layer", 3); m.SetFloat("_Tiling", ship ? 1.2f : 3f); m.SetFloat("_Detail", 0.45f); m.SetFloat("_NormalStrength", 0.8f);
                    m.SetFloat("_Metallic", 0.65f); m.SetFloat("_TexRough", 0.7f);
                    break;
                case MatClass.Paint:
                    m.SetFloat("_Layer", 4); m.SetFloat("_Tiling", ship ? 1.2f : 3f); m.SetFloat("_Detail", 0.35f); m.SetFloat("_NormalStrength", 0.6f);
                    m.SetFloat("_Metallic", 0.15f); m.SetFloat("_TexRough", 0.6f);
                    break;
                case MatClass.Foliage:
                    m.SetFloat("_Layer", -1); m.SetFloat("_Wind", 0.28f); m.SetFloat("_Translucency", 0.55f);
                    m.SetFloat("_GroundAO", 0.5f); m.SetFloat("_AOHeight", 2.5f); m.SetFloat("_Cull", (float)CullMode.Off);
                    break;
                case MatClass.Plain:
                    m.SetFloat("_Layer", -1);
                    break;
                case MatClass.Glass:
                    m.SetFloat("_Layer", -1); m.SetFloat("_Metallic", 0.1f); m.SetFloat("_GroundAO", 0f);
                    break;
            }
        }

        [MenuItem("Stardust/Import World/3. Materials")]
        public static void ImportMaterials()
        {
            Mat("Terrain", "Stardust/Terrain", m =>
            {
                m.SetTexture("_Albedo", Load<Texture2DArray>("terrain_albedo.png"));
                m.SetTexture("_Normal", Load<Texture2DArray>("terrain_normal.png"));
                m.SetTexture("_Biome", Load<Texture2D>("biome.png"));
                m.SetTexture("_Roads", Load<Texture2D>("roads.png"));
                m.SetFloat("_WorldSize", 24576f);
                m.SetFloat("_Tiling", 7f);
                m.SetFloat("_RockTiling", 16f);
                m.SetFloat("_NormalStrength", 1f);
                m.SetFloat("_Quality", 1f);
                m.enableInstancing = false;
            });
            Mat("Ocean", "Stardust/Water", m =>
            {
                m.SetTexture("_WaveNormal", Load<Texture2D>("water_normal.png"));
                m.SetTexture("_OceanMask", Load<Texture2D>("ocean_mask.png"));
                m.SetFloat("_UseMask", 1f);
                m.SetFloat("_WorldSize", 24576f);
                m.SetFloat("_WaveScale", 42f);
                m.enableInstancing = false;
            });
            Mat("Lake", "Stardust/Water", m =>
            {
                m.SetTexture("_WaveNormal", Load<Texture2D>("water_normal.png"));
                m.SetFloat("_UseMask", 0f);
                m.SetFloat("_WaveScale", 24f);
                m.SetColor("_Deep", new Color(0.03f, 0.14f, 0.13f));
                m.SetColor("_Shallow", new Color(0.09f, 0.33f, 0.3f));
                m.enableInstancing = false;
            });
            Mat("Sky", "Stardust/SkyHD", m => { m.enableInstancing = false; });
            Mat("Grass", "Stardust/Grass", m =>
            {
                m.SetTexture("_Biome", Load<Texture2D>("biome.png"));
                m.SetTexture("_Roads", Load<Texture2D>("roads.png"));
                m.SetFloat("_WorldSize", 24576f);
            });
            foreach (MatClass c in Enum.GetValues(typeof(MatClass)))
            {
                Mat("World_" + c, "Stardust/WorldLit", m => ClassSettings(m, c, false));
                Mat("Ship_" + c, "Stardust/WorldLit", m => ClassSettings(m, c, true));
            }
            AssetDatabase.SaveAssets();
            Debug.Log("[WorldImporter] materials ready");
        }

        // ------------------------------------------------------------------ models (SDW1)

        static readonly Dictionary<string, MatClass> PaletteClass = new Dictionary<string, MatClass>();

        static MatClass ClassOf(string pal)
        {
            if (PaletteClass.Count == 0)
            {
                void Set(MatClass c, params string[] names) { foreach (var n in names) PaletteClass[n] = c; }
                Set(MatClass.Rock, "base", "sand_light", "sand", "sand_orange", "rust", "rust_dark", "glyph", "moss", "moss_dark",
                    "rock_lav", "rock_grey", "rock", "rock_dark", "tunnel", "tunnel_floor", "stone_light", "stone", "stone_dark",
                    "stone_eye", "bone", "bone_dark", "bone_socket");
                Set(MatClass.Concrete, "cream", "cream_dark", "orange_band", "window");
                Set(MatClass.Bark, "trunk", "bark", "bark_grey", "palm_trunk", "stem");
                Set(MatClass.Foliage, "leaf_light", "leaf", "leaf_dark", "grass", "palm_leaf", "palm_leaf_light", "pine", "pine_light",
                    "giant_leaf", "giant_leaf_light", "giant_leaf_dark", "fern", "flower_pink", "flower_yellow", "flower_white",
                    "flower_violet", "flower_red");
                Set(MatClass.Metal, "hull", "hull_dark", "hull_light", "hull_rust", "p_metal", "p_dark", "p_rust");
                Set(MatClass.Paint, "p_orange", "p_cream", "v_white", "v_red", "v_navy", "v_helmet");
                Set(MatClass.Glass, "v_glass");
            }
            return PaletteClass.TryGetValue(pal, out var c) ? c : MatClass.Plain;
        }

        class Pal { public string name; public Color c; public float rough; public Color em; public float strength; }

        /// <summary>Crease angle for the smooth normals of each model (natural shapes smooth, architecture crisp).</summary>
        static float SmoothAngle(string name)
        {
            if (name.EndsWith("_hd")) name = name.Substring(0, name.Length - 3);
            if (name.StartsWith("tunel") || name.StartsWith("ponte") || name == "canyon_roof") return 55f;
            switch (name)
            {
                case "rock_spire_a": case "rock_spire_b": case "rock_spire_c": case "mesa": case "arch": case "arch_giant":
                case "arch_twin": case "rock_ring": case "rock_fin": case "butte": case "boulder_a": case "boulder_b":
                case "float_island": case "colosso_estatua": case "colosso_costelas":
                    return 62f;
                case "tree_acacia": case "tree_acacia_b": case "tree_giant": case "pine": case "palm": case "bush": case "fern":
                case "flowers": case "grass_tuft": case "dead_tree": case "cactus": case "tree_mushroom":
                    return 75f;
                case "grazer": case "grazer_tall":
                    return 60f;
                default:
                    return 28f;   // ruins, pillars, pyramid, obelisk, crystals, vehicles
            }
        }

        /// <summary>
        /// Tree crowns: normals bent outwards from the centre of each leaf cluster (cone axis for pines), so a
        /// low-poly canopy is lit like a soft volume of leaves instead of flat facets.
        /// </summary>
        static void FluffyNormals(string name, Vector3[] pos, Vector3[] nrm, MatClass[] cls, int nt)
        {
            if (name.EndsWith("_hd")) name = name.Substring(0, name.Length - 3);
            bool pine = name == "pine";
            if (!(pine || name == "tree_acacia" || name == "tree_acacia_b" || name == "tree_giant" || name == "bush" || name == "float_island")) return;
            // connected components of foliage triangles (shared corner positions)
            var key = new Func<Vector3, (int, int, int)>(p => (Mathf.RoundToInt(p.x * 200f), Mathf.RoundToInt(p.y * 200f), Mathf.RoundToInt(p.z * 200f)));
            var parent = new int[nt];
            for (int i = 0; i < nt; i++) parent[i] = i;
            int Find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
            var owner = new Dictionary<(int, int, int), int>();
            for (int t = 0; t < nt; t++)
            {
                if (cls[t] != MatClass.Foliage) continue;
                for (int k = 0; k < 3; k++)
                {
                    var kk = key(pos[t * 3 + k]);
                    if (owner.TryGetValue(kk, out int o2)) parent[Find(t)] = Find(o2); else owner[kk] = t;
                }
            }
            var sum = new Dictionary<int, Vector3>();
            var cnt = new Dictionary<int, int>();
            for (int t = 0; t < nt; t++)
            {
                if (cls[t] != MatClass.Foliage) continue;
                int r = Find(t);
                var c = (pos[t * 3] + pos[t * 3 + 1] + pos[t * 3 + 2]) / 3f;
                sum[r] = sum.TryGetValue(r, out var s) ? s + c : c;
                cnt[r] = cnt.TryGetValue(r, out int n) ? n + 1 : 1;
            }
            for (int t = 0; t < nt; t++)
            {
                if (cls[t] != MatClass.Foliage) continue;
                int r = Find(t);
                var centre = sum[r] / cnt[r];
                for (int k = 0; k < 3; k++)
                {
                    int v = t * 3 + k;
                    Vector3 outward = pine ? new Vector3(pos[v].x, 0f, pos[v].z).normalized + Vector3.up * 0.45f : (pos[v] - centre);
                    if (outward.sqrMagnitude < 1e-6f) continue;
                    nrm[v] = Vector3.Lerp(nrm[v], outward.normalized, pine ? 0.6f : 0.7f).normalized;
                }
            }
        }

        /// <summary>Area-weighted vertex normals across triangles that share a position, within a crease angle.</summary>
        static void SmoothNormals(Vector3[] pos, Vector3[] nrm, int nt, float angle)
        {
            var fn = new Vector3[nt];
            var area = new float[nt];
            for (int t = 0; t < nt; t++)
            {
                fn[t] = (nrm[t * 3] + nrm[t * 3 + 1] + nrm[t * 3 + 2]).normalized;
                area[t] = Vector3.Cross(pos[t * 3 + 1] - pos[t * 3], pos[t * 3 + 2] - pos[t * 3]).magnitude * 0.5f + 1e-6f;
            }
            var groups = new Dictionary<(int, int, int), List<int>>();
            for (int v = 0; v < pos.Length; v++)
            {
                var k = (Mathf.RoundToInt(pos[v].x * 500f), Mathf.RoundToInt(pos[v].y * 500f), Mathf.RoundToInt(pos[v].z * 500f));
                if (!groups.TryGetValue(k, out var l)) groups[k] = l = new List<int>();
                l.Add(v);
            }
            float cos = Mathf.Cos(angle * Mathf.Deg2Rad);
            var outN = new Vector3[pos.Length];
            foreach (var l in groups.Values)
                foreach (int v in l)
                {
                    var f = fn[v / 3];
                    var s = Vector3.zero;
                    foreach (int u in l)
                    {
                        var g = fn[u / 3];
                        if (Vector3.Dot(f, g) >= cos) s += g * area[u / 3];
                    }
                    outN[v] = s.sqrMagnitude > 1e-12f ? s.normalized : f;
                }
            Array.Copy(outN, nrm, nrm.Length);
        }

        [MenuItem("Stardust/Import World/4. Models")]
        public static void ImportModels()
        {
            var bytes = File.ReadAllBytes($"{Src}/models.bytes");
            int o = 0;
            int I32() { int v = BitConverter.ToInt32(bytes, o); o += 4; return v; }
            float F() { float v = BitConverter.ToSingle(bytes, o); o += 4; return v; }
            string S() { int n = I32(); var s = Encoding.UTF8.GetString(bytes, o, n); o += n; return s; }
            if (Encoding.ASCII.GetString(bytes, 0, 4) != "SDW1") throw new Exception("models.bytes: bad magic");
            o = 4;
            int np = I32();
            var pal = new Pal[np];
            for (int i = 0; i < np; i++)
            {
                var p = new Pal { name = S() };
                p.c = new Color(F(), F(), F());
                p.rough = F();
                p.em = new Color(F(), F(), F());
                p.strength = F();
                pal[i] = p;
            }
            int nm = I32();
            var libPath = $"{Res}/Models.asset";
            AssetDatabase.DeleteAsset(libPath);
            var lib = ScriptableObject.CreateInstance<ModelLibrary>();
            AssetDatabase.CreateAsset(lib, libPath);
            var report = new StringBuilder();
            int totalTris = 0;
            for (int mi = 0; mi < nm; mi++)
            {
                string name = S();
                int nt = I32();
                var pos = new Vector3[nt * 3];
                var nrm = new Vector3[nt * 3];
                var col = new Color32[nt * 3];
                var surf = new Vector2[nt * 3];
                var cls = new MatClass[nt];
                for (int t = 0; t < nt; t++)
                {
                    for (int k = 0; k < 3; k++)
                    {
                        int v = t * 3 + k;
                        pos[v] = new Vector3(F(), F(), F());
                        nrm[v] = new Vector3(F(), F(), F());
                        col[v] = new Color32(bytes[o], bytes[o + 1], bytes[o + 2], bytes[o + 3]);
                        o += 4;
                    }
                    int pid = BitConverter.ToUInt16(bytes, o);
                    o += 2;
                    var p = pal[Mathf.Clamp(pid, 0, np - 1)];
                    cls[t] = ClassOf(p.name);
                    for (int k = 0; k < 3; k++) surf[t * 3 + k] = new Vector2(p.rough, p.strength);
                }
                SmoothNormals(pos, nrm, nt, SmoothAngle(name));
                FluffyNormals(name, pos, nrm, cls, nt);
                // winding: Blender (right-handed) -> Unity (left-handed, clockwise front faces)
                int agree = 0;
                for (int t = 0; t < nt; t++)
                {
                    var c = Vector3.Cross(pos[t * 3 + 1] - pos[t * 3], pos[t * 3 + 2] - pos[t * 3]);
                    if (Vector3.Dot(c, nrm[t * 3] + nrm[t * 3 + 1] + nrm[t * 3 + 2]) > 0f) agree++;
                }
                bool flip = agree < nt / 2;
                var groups = new Dictionary<MatClass, List<int>>();
                for (int t = 0; t < nt; t++)
                {
                    if (!groups.TryGetValue(cls[t], out var l)) groups[cls[t]] = l = new List<int>();
                    if (flip) { l.Add(t * 3); l.Add(t * 3 + 2); l.Add(t * 3 + 1); }
                    else { l.Add(t * 3); l.Add(t * 3 + 1); l.Add(t * 3 + 2); }
                }
                var mesh = new Mesh { name = name };
                if (pos.Length > 65000) mesh.indexFormat = IndexFormat.UInt32;
                mesh.vertices = pos;
                mesh.normals = nrm;
                mesh.colors32 = col;
                mesh.uv2 = surf;
                var keys = new List<MatClass>(groups.Keys);
                keys.Sort();
                mesh.subMeshCount = keys.Count;
                for (int s = 0; s < keys.Count; s++) mesh.SetTriangles(groups[keys[s]], s, true);
                mesh.RecalculateBounds();
                mesh.UploadMeshData(false);
                AssetDatabase.AddObjectToAsset(mesh, lib);
                lib.models.Add(new ModelLibrary.Entry { name = name, mesh = mesh, classes = keys.ToArray(), bounds = mesh.bounds });
                totalTris += nt;
                report.AppendLine($"  {name,-20} {nt,6} tris  flip={flip} ({agree}/{nt})  classes {string.Join(",", keys)}  size {mesh.bounds.size}");
            }
            var mats = new Material[Enum.GetValues(typeof(MatClass)).Length];
            var shipMats = new Material[mats.Length];
            foreach (MatClass c in Enum.GetValues(typeof(MatClass)))
            {
                mats[(int)c] = AssetDatabase.LoadAssetAtPath<Material>($"{Res}/Materials/World_{c}.mat");
                shipMats[(int)c] = AssetDatabase.LoadAssetAtPath<Material>($"{Res}/Materials/Ship_{c}.mat");
            }
            lib.materials = mats;
            lib.shipMaterials = shipMats;
            EditorUtility.SetDirty(lib);
            AssetDatabase.SaveAssets();
            Debug.Log($"[WorldImporter] {nm} models, {totalTris} triangles\n{report}");
        }

        // ------------------------------------------------------------------ terrain

        [MenuItem("Stardust/Import World/5. Terrain")]
        public static void ImportTerrain()
        {
            var raw = File.ReadAllBytes($"{Src}/unity/height.r32");
            int res = (int)Math.Round(Math.Sqrt(raw.Length / 4));
            if (res != (TileRes - 1) * Tiles + 1) throw new Exception($"height.r32: unexpected resolution {res}");
            var dir = $"{Res}/Terrain";
            Folder(dir);
            float hmin = float.MaxValue, hmax = float.MinValue;
            for (int j = 0; j < Tiles; j++)
            {
                for (int i = 0; i < Tiles; i++)
                {
                    var h = new float[TileRes, TileRes];
                    for (int z = 0; z < TileRes; z++)
                    {
                        int row = j * (TileRes - 1) + z;
                        for (int x = 0; x < TileRes; x++)
                        {
                            int col = i * (TileRes - 1) + x;
                            float m = BitConverter.ToSingle(raw, (row * res + col) * 4);
                            hmin = Mathf.Min(hmin, m); hmax = Mathf.Max(hmax, m);
                            h[z, x] = Mathf.Clamp01((m - HMin) / HRange);
                        }
                    }
                    var path = $"{dir}/t_{i}_{j}.asset";
                    var td = AssetDatabase.LoadAssetAtPath<TerrainData>(path);
                    if (td == null)
                    {
                        td = new TerrainData();
                        AssetDatabase.CreateAsset(td, path);
                    }
                    td.heightmapResolution = TileRes;
                    td.alphamapResolution = 16;
                    td.baseMapResolution = 16;
                    td.SetDetailResolution(0, 8);
                    td.size = new Vector3(TileSize, HRange, TileSize);
                    td.SetHeights(0, 0, h);
                    EditorUtility.SetDirty(td);
                }
            }
            AssetDatabase.SaveAssets();
            Debug.Log($"[WorldImporter] terrain: {Tiles}x{Tiles} tiles of {TileRes}, heights {hmin:0.0}..{hmax:0.0} m");
        }
    }
}
